import React from 'react';

function App() {
  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h1 style={{ color: '#0ea5e9' }}>🎉 Digital Wallet - Test Page</h1>
      <p>If you can see this, React is working!</p>
      <div style={{ 
        background: '#f0f9ff', 
        padding: '20px', 
        borderRadius: '8px', 
        margin: '20px 0' 
      }}>
        <h2>✅ Status Check</h2>
        <ul>
          <li>✅ React App Loading</li>
          <li>✅ JavaScript Working</li>
          <li>✅ Styles Applied</li>
        </ul>
      </div>
      <button 
        onClick={() => alert('Button clicked! React is working perfectly!')}
        style={{
          background: '#0ea5e9',
          color: 'white',
          padding: '10px 20px',
          border: 'none',
          borderRadius: '5px',
          cursor: 'pointer'
        }}
      >
        Test Button
      </button>
      <div style={{ marginTop: '20px', padding: '15px', background: '#dcfce7', borderRadius: '8px' }}>
        <h3>🚀 Next Steps:</h3>
        <p>Once this test page loads, we'll restore the full Digital Wallet application!</p>
      </div>
    </div>
  );
}

export default App;
